import { useContext } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import './photos.scss';

const Photos = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);

  if (!currentUser) {
    return null;
  }

  // Mock photos data (replace with API)
  const photos = [
    { id: 1, url: 'https://images.pexels.com/photos/39811/pexels-photo-39811.jpeg', caption: 'Nature' },
    { id: 2, url: 'https://images.pexels.com/photos/235615/pexels-photo-235615.jpeg', caption: 'City' },
  ];

  return (
    <div className={`photos ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h2>{currentUser.name}'s Photos</h2>
      <div className="photo-grid">
        {photos.map(photo => (
          <div key={photo.id} className="photo-card">
            <img src={photo.url} alt={photo.caption} />
            <p>{photo.caption}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Photos;
